-- POLARIS seed data
--
-- Generated by `npm run seed --workspace @polaris/catalog`. Do not edit by
-- hand: the catalog is generated, and the seed is generated from it.
--
-- Every statement is an upsert on the primary key, so the seed is
-- idempotent and can be re-run after a catalog change.

begin;

-- 240 tools
on conflict (id) do update set
  category = excluded.category,
  name = excluded.name,
  description = excluded.description,
  descriptor = excluded.descriptor,
  input_schema = excluded.input_schema,
  x = excluded.x,
  y = excluded.y;

-- 863 evaluation queries
on conflict (id) do update set
  query = excluded.query,
  label_tool = excluded.label_tool,
  kind = excluded.kind,
  split = excluded.split;

commit;
